#include "ui/OrbaMirrorModel.h"
#include <algorithm>
namespace jeff::daw {void OrbaMirrorModel::consume(const PerformanceEvent&e)noexcept{apply(e);++state.revision;}void OrbaMirrorModel::apply(const PerformanceEvent&e)noexcept{auto&p=state.pads[e.note%8];p.lastActivity=e.sampleTime;if(e.type==PerformanceEventType::noteOn){p.held=true;p.intensity=e.value;}else if(e.type==PerformanceEventType::noteOff)p.held=false;else if(e.type==PerformanceEventType::expression){if(e.expressionKind==ExpressionKind::pressure){p.pressure=e.value;p.intensity=std::max(p.intensity,e.value);}else if(e.expressionKind==ExpressionKind::pitch)p.pitch=e.value;else if(e.expressionKind==ExpressionKind::timbre)p.timbre=e.value;}}void OrbaMirrorModel::tick(std::int64_t now)noexcept{bool c=false;for(auto&p:state.pads){if(overflow&&p.held&&now-p.lastActivity>=2000){p.held=false;p.intensity=0;c=true;}else if(!p.held&&p.intensity&&now-p.lastActivity>=180){p.intensity=0;c=true;}}if(overflow&&c){state.warning="Input overflow recovered";overflow=false;}if(c)++state.revision;}void OrbaMirrorModel::setProfile(ProfileKind p){state.modelLabel=p==ProfileKind::orba1?"Orba 1":p==ProfileKind::orba2?"Orba 2":p==ProfileKind::jt4000?"JT-4000 Micro":"Generic MIDI";++state.revision;}}
